    spec = Path() if not spec_text else (ast.literal_eval(spec_text) if spec_format == 'python' and spec_text[0] not in ('"', "'", "[", "{", "(") else json.loads(spec_text) if spec_format == 'json' else _eval_python_full_spec(spec_text) if spec_format == 'python-full' else raise UsageError('expected spec-format to be one of json, python, or python-full'))
    if target_text and target_file:
