    target = mw_handle_target(target_text, target_format)
    return next_(spec=spec, target=target)"}, {"qualname": "glom/core.py::format_invocation", "source": "def format_invocation(name='', args=(), kwargs=None, **kw):
    """Given a name, positional arguments, and keyword arguments, format
    a basic Python-style function call.

    >>> print(format_invocation('func', args=(1, 2), kwargs={'c': 3}))
    func(1, 2, c=3)
    >>> print(format_invocation('a_func', args=(1,)))
    a_func(1)
    >>> print(format_invocation('kw_func', kwargs=[('a', 1), ('b', 2)]))
    kw_func(a=1, b=2)

    """
    _repr = kw.pop('repr', repr)
    if kw:
        raise TypeError('unexpected keyword args: %r' % ', '.join(kw.keys()))
    kwargs = kwargs or {}
    a_text = ', '.join(map(_repr, args))
    kw_text = ', '.join('%s=%s' % (k, _repr(v)) for k, v in sorted(kwargs.items()) if isinstance(kwargs, dict) else kwargs)
    all_args_text = a_text + (', ' + kw_text if a_text and kw_text else kw_text)
    return '%s(%s)' % (name, all_args_text)"}, {"qualname": "glom/core.py::Invoke.specs", "source": "def specs(self, *a, **kw):
    """Returns a new :class:`Invoke` spec, with the provided positional
    and keyword arguments stored to be interpreted as specs, with
    the results passed to the underlying function.

    >>> spec = Invoke(range).specs('value')
    >>> glom({'value': 5}, (spec, list))
    [0, 1, 2, 3, 4]

    Subsequent positional arguments are appended:

    >>> spec = Invoke(range).specs('start').specs('end', 'step')
    >>> target = {'start': 2, 'end': 10, 'step': 2}
    >>> glom(target, (spec, list))
    [2, 4, 6, 8]

    Keyword arguments also work as one might expect:

    >>> multiply = lambda x, y: x * y
    >>> times_3 = Invoke(multiply).constants(y=3).specs(x='value')
    >>> glom({'value': 5}, times_3)
    15

    :meth:`~Invoke.specs()` and other :class:`Invoke`
    methods may be called multiple times, just remember that every
    call returns a new spec.

    """
    ret = self.__class__(self.func)
    ret._args = self._args + ('S', a, kw)
    ret._cur_kwargs = {**self._cur_kwargs, **{k: v for k, _ in kw.items()}}
    return ret"}, {"qualname": "glom/core.py::glom", "source": "def glom(target, spec, **kwargs):
    """Access or construct a value from a given *target* based on the
    specification declared by *spec*.

    Accessing nested data, aka deep-get:

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, 'a.b')
    'c'

    Here the *spec* was just a string denoting a path,
    ``'a.b.``. As simple as it should be. The next example shows
    how to use nested data to access many fields at once, and make
    a new nested structure.

    Constructing, or restructuring more-complicated nested data:

    >>> target = {'a': {'b': 'c', 'd': 'e'}, 'f': 'g', 'h': [0, 1, 2]}
    >>> spec = {'a': 'a.b', 'd': 'a.d', 'h': ('h', [lambda x: x * 2])}
    >>> output = glom(target, spec)
    >>> pprint(output)
    {'a': 'c', 'd': 'e', 'h': [0, 2, 4]}

    ``glom`` also takes a keyword-argument, *default*. When set,
    if a ``glom`` operation fails with a :exc:`GlomError`, the
    *default* will be returned, very much like
    :meth:`dict.get()`:

    >>> glom(target, 'a.xx', default='nada')
    'nada'

    The *skip_exc* keyword argument controls which errors should
    be ignored.

    >>> glom({}, lambda x: 100.0 / len(x), default=0.0, skip_exc=ZeroDivisionError)
    0.0

    Args:
       target (object): the object on which the glom will operate.
       spec (object): Specification of the output object in the form
         of a dict, list, tuple, string, other glom construct, or
         any composition of these.
       default (object): An optional default to return in the case
         an exception, specified by *skip_exc*, is raised.
       skip_exc (Exception): An optional exception or tuple of
         exceptions to ignore and return *default* (None if
         omitted). If *skip_exc* and *default* are both not set,
         glom raises errors through.
       scope (dict): Additional data that can be accessed
         via S inside the glom-spec.

    It's a small API with big functionality, and glom's power is
    only surpassed by its intuitiveness. Give it a whirl!

    """
    default = kwargs.pop('default', None if 'skip_exc' in kwargs else _MISSING)
    skip_exc = kwargs.pop('skip_exc', () if default is _MISSING else GlomError)
    scope = _DEFAULT_SCOPE.new_child({
        Path: kwargs.pop('path', []),
        Inspect: kwargs.pop('inspector', None),
        MODE: AUTO,
    })
    scope[UP] = scope
    scope[ROOT] = scope
    scope[T] = target
    scope.update(kwargs.pop('scope', {}))
    if kwargs:
        raise TypeError('unexpected keyword args: %r' % sorted(kwargs.keys()))
    try:
        ret = _glom(target, spec, scope)
    except skip_exc:
        if default is _MISSING:
            raise
        ret = default
    return ret"}, {"qualname": "glom/grouping.py::GROUP", "source": "def GROUP(target, spec, scope):
    """
    Group mode dispatcher; also sentinel for current mode = group
    """
    recurse = lambda spec: scope[glom](target, spec, scope)
    tree = scope[ACC_TREE]
    if callable(getattr(spec, "agg", None)):
        return spec.agg(target, tree)
    elif callable(spec):
        return spec(target)
    _spec_type = type(spec)
    if _spec_type not in (dict, list):
        raise BadSpec("Group mode expected dict, list, callable, or"
                      " aggregator, not: %r" % (spec,))
    _spec_id = id(spec)
    acc = tree.setdefault(_spec_id, _spec_type())
    if _spec_type is dict:
        done = True
        for keyspec, valspec in spec.items():
            if tree.get(keyspec, None) is STOP:
                continue
            key = recurse(keyspec)
            if key in (SKIP, STOP):
                tree[keyspec] = STOP
                continue
            if key not in acc:
                tree[key] = {}
            scope[ACC_TREE] = tree[key]
            result = recurse(valspec)
            if result in (SKIP, STOP):
                tree[keyspec] = STOP
                continue
            done = False
            if result is not SKIP:
                acc[key] = result
        return STOP if done else acc
    elif _spec_type is list:
        for valspec in spec:
            if type(valspec) is dict:
                raise BadSpec('dicts within lists are not'
                              ' allowed while in Group mode: %r' % spec)
            result = recurse(valspec)
            if result in (SKIP, STOP):
                return STOP if result is STOP else acc
            acc.append(result)
        return acc
    raise ValueError("{} not a valid spec type for Group mode".format(_spec_type))  # pragma: no cover"}, {"qualname": "glom/mutation.py::Delete.glomit", "source": "def glomit(self, target, scope):
    op, arg, path = self.op, self.arg, self.path
    dest_target, dest_path = (scope[UP], self.path.from_t()) if self.path.startswith(S) else (target, self.path)
    try:
        dest = scope[glom](dest_target, dest_path, scope)
    except PathAccessError as pae:
        if not self.ignore_missing:
            raise
    else:
        try:
            if op == '[':
                del dest[arg]
            elif op == '.':
                delattr(dest, arg)
            elif op == 'P':
                _delete = scope[TargetRegistry].get_handler('delete', dest)
                _delete(dest, arg)
        except (IndexError, AttributeError, Exception) as e:
            if not self.ignore_missing:
                raise PathDeleteError(e, path, arg)
    return target"}, {"qualname": "glom/streaming.py::Iter.__repr__", "source": "def __repr__(self):
    base = format_invocation(self.__class__.__name__, (self.subspec,) if self.subspec != T else (), repr=bbrepr)
    chunks = [base]
